/* Tidelight local interactions. All images and fit traces are recorded assets. */
(()=>{'use strict';
const D=window.TIDELIGHT_DATA,$=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
if(!D){console.error('Tidelight data is missing.');return;}
const controls=D.controls||Object.fromEntries(Object.keys(D.defaults).map(k=>[k,{low:D.bounds[k][0],default:D.defaults[k],high:D.bounds[k][1]}]));
const RAW=String.raw,video=$('#reveal-video'),sections=D.storyboard.sections;
const stageNames=['','01-wire','02-stone','03-water','04-materials','05-light','06-final','06-final'];
const chapterCopy=[
['An image, assembled from ingredients.','A renderer combines geometry, materials, light, volume and a camera into the image you see.','G: geometry · M: materials · L: lights · V: volume · C: camera. This expression is a schematic of the renderer.',544],
['First, give the world a shape.','Scaled and displaced sphere meshes establish the rocks. This coarse wireframe makes the topology visible.','p is a unit-sphere point. s controls scale; r gives radial relief; g includes the vertical warp and top/bottom shaping.',256],
['Let the stone become irregular.','Broad sine and cosine warps meet three frequencies of Perlin noise. The surface breaks into eroded ridges and facets.','P is Perlin noise. φ varies between rocks. This radial expression is one part of the complete coordinate transform.',268],
['Three waves give the water its shape.','Three sine terms add together to displace the water mesh. Their directions and wavelengths differ.','x and y are local mesh coordinates. Height is in scene units. Fine shader normals add smaller surface details.',388],
['The surfaces catch their reflections.','Roughness, procedural bump and a thin coat create the wet response. Water has a fixed base color and layered wave normals.','r denotes the roughness control, w the coat weight, H a procedural bump field. IOR is the index of refraction.',65],
['Light turns the construction into a place.','Warm grazing sunlight, cool fill and the authored sky bring out the relief. Cycles estimates light transport by path tracing.','Lo: outgoing radiance · Le: emission · fr: surface scattering · Li: incident radiance · n: normal · ω: incoming direction.',309],
['Mist gives the distance its depth.','The density decreases with height. The renderer scatters and attenuates light through this volume, separating the layers of rock.','z is vertical position inside the authored volume. ρ is the density control; σt is extinction along a ray; T is transmission.',233],
['A landscape, made inspectable.','The geometry, materials, light, volume and camera now work together. Explore the individual ingredients below.','The final scene is restored after diagnostic views. Blender Cycles and denoising remain part of the image-making process.',544]
];
function math(el,formula){el.textContent='';katex.render(formula,el,{displayMode:true,throwOnError:true,output:'htmlAndMathml',trust:false});}
function maths(el,formulae){el.replaceChildren();for(const f of formulae){const line=document.createElement('div');math(line,f);el.append(line);}}
function pressed(selector,attribute,value){$$(selector).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset[attribute]===value)));}
let mode='film',chapter=-1,mediaReady=false,mediaPromise=null;
// Pages serves the full MP4 even for Range requests. A local Blob gives the
// native player reliable chapter seeking after one user-initiated download.
function ensureVideo(){
 if(mediaReady)return Promise.resolve();if(mediaPromise)return mediaPromise;
 $('#mode-note').textContent='Preparing the film · 8.6 MB';
 mediaPromise=(async()=>{
  const response=await fetch('assets/tidelight-math-reveal.mp4');
  if(!response.ok)throw new Error('Film download failed');
  const blob=await response.blob();if(!blob.size)throw new Error('Empty film');
  video.pause();video.src=URL.createObjectURL(blob);
  await new Promise((resolve,reject)=>{video.addEventListener('loadedmetadata',resolve,{once:true});video.addEventListener('error',reject,{once:true});video.load();});
  mediaReady=true;$('#mode-note').textContent='64 seconds · silent · ready to explore';
 })().catch(error=>{mediaPromise=null;$('#mode-note').textContent='Film could not load. Try again, or use Keep the film below.';throw error;});
 return mediaPromise;
}
video.addEventListener('play',()=>{if(!mediaReady){video.pause();ensureVideo().then(()=>video.play()).catch(()=>{});}});
function showChapter(i){if(i===chapter)return;chapter=i;const s=sections[i],c=chapterCopy[i];$('#chapter-label').textContent=s.short;$('#chapter-title').textContent=c[0];$('#chapter-description').textContent=c[1];$('#chapter-definitions').textContent=c[2];$('#chapter-source').href='source.html#L'+c[3];$('#chapter-source-extra').hidden=i!==4;maths($('#chapter-equations'),s.equations.length?s.equations:[sections[0].equations[0]]);$$('[data-chapter]').forEach(b=>b.setAttribute('aria-current',String(+b.dataset.chapter===i)));if(mode==='stills'){const ix=Math.max(1,i);$('#stage-image').src='assets/stages/'+stageNames[ix]+'.webp';$('#stage-image').alt=chapterCopy[ix][0]+' '+chapterCopy[ix][1];$('#gallery-badge').textContent=sections[ix].short;}}
function presentation(next){mode=next;$('#mode-film').setAttribute('aria-pressed',String(next==='film'));$('#mode-stills').setAttribute('aria-pressed',String(next==='stills'));video.hidden=next!=='film';$('#stage-gallery').hidden=next!=='stills';$('#mode-note').textContent=next==='film'?'64 seconds · silent · play when ready':'Manual stages · no automatic motion';if(next==='stills'){video.pause();const i=Math.max(1,chapter);chapter=-1;showChapter(i);}else{showChapter(video.ended?7:Math.max(0,sections.findIndex(s=>video.currentTime>=s.start&&video.currentTime<s.end))); }}
function seek(t){video.pause();ensureVideo().then(()=>{video.currentTime=t;}).catch(()=>{});}
video.addEventListener('timeupdate',()=>{if(mode==='film')showChapter(Math.max(0,sections.findIndex(s=>video.currentTime>=s.start&&video.currentTime<s.end)));});
video.addEventListener('ended',()=>showChapter(7));
$('#mode-film').addEventListener('click',()=>presentation('film'));$('#mode-stills').addEventListener('click',()=>presentation('stills'));
$('#hero-play').addEventListener('click',()=>{presentation('film');ensureVideo().then(()=>video.play()).catch(()=>{});});
$$('[data-chapter]').forEach(b=>b.addEventListener('click',()=>{const i=+b.dataset.chapter;showChapter(i);if(mode==='film')seek(sections[i].start+3.2);}));
showChapter(0);if(matchMedia('(prefers-reduced-motion: reduce)').matches)presentation('stills');
sections.forEach((s,i)=>{const article=document.createElement('article');const t=document.createElement('p');t.className='eyebrow teal';t.textContent=`${String(s.start).padStart(2,'0')}–${String(s.end).padStart(2,'0')} seconds / ${s.short}`;const h=document.createElement('h3');h.textContent=chapterCopy[i][0];const p=document.createElement('p');p.textContent=chapterCopy[i][1]+' '+chapterCopy[i][2];const m=document.createElement('div');m.className='math-stack';maths(m,s.equations);article.append(t,h,m,p);$('#transcript').append(article);});
const controlCopy={mist_density:{symbol:'ρ',name:'Mist',kicker:'HEIGHT-DEPENDENT DENSITY',description:'More mist scatters and attenuates light along the view, softening distant forms.',form:v=>[RAW`\rho=${v}`,RAW`D(z)=\rho\!\left[0.65-0.62\,\mathrm{clip}\!\left(\frac{z+1}{26},0,1\right)\right]`]},key_energy:{symbol:'E',name:'Light',kicker:'SUNLIGHT ENERGY',description:'Change the sunlight energy while the sky and cool fill stay fixed. Notice where the warm highlights gain strength.',form:v=>[RAW`E_{\mathrm{sun}}=${v}`,RAW`L_o=L_e+\int_\Omega f_r L_i |\mathbf{n}\cdot\boldsymbol\omega|\,d\boldsymbol\omega`]},water_roughness:{symbol:'r',name:'Water',kicker:'WATER ROUGHNESS',description:'A smoother surface gives tighter reflections. Increased roughness spreads reflected light; the water geometry stays the same.',form:v=>[RAW`r_{\mathrm{water}}=${v}`,RAW`\mathrm{IOR}_{\mathrm{water}}=1.333`]}};
let control='mist_density',level='default';
function updateControl(){const c=controlCopy[control],v=controls[control][level];pressed('[data-control]','control',control);pressed('[data-level]','level',level);$('#control-symbol').textContent=c.symbol;$('#control-value').textContent=v.toFixed(control==='key_energy'?1:3);$('#control-kicker').textContent=c.kicker;$('#control-description').textContent=c.description;$('#control-image').src=`assets/controls/${control}-${level}.webp`;$('#control-image').alt=`${c.name} at ${level} setting (${v}) with all other controls at defaults`;$('#control-image-label').textContent=`${c.name.toUpperCase()} / ${level.toUpperCase()}`;maths($('#control-equation'),c.form(v));}
$$('[data-control]').forEach(b=>b.addEventListener('click',()=>{control=b.dataset.control;level='default';updateControl();}));$$('[data-level]').forEach(b=>b.addEventListener('click',()=>{level=b.dataset.level;updateControl();}));updateControl();
const NS='http://www.w3.org/2000/svg';function svg(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n;}
const waveColors=['#dfa483','#8acbc7','#a59cc9'],waveTerms=[RAW`0.060\sin(0.42x+0.095y)`,RAW`0.030\sin(0.93x-0.16y+1.7)`,RAW`0.015\sin(1.8x+0.41y)`];
function drawWave(){const enabled=$$('[data-wave]').map(x=>x.checked),y=+$('#wave-y').value;$('#wave-y-value').textContent=y.toFixed(1);const grid=$('#wave-grid'),paths=$('#wave-paths');grid.replaceChildren();paths.replaceChildren();const sx=x=>50+(x+20)/40*685,sy=h=>150-h/0.12*120;
for(const h of[-.1,0,.1]){grid.append(svg('line',{x1:50,y1:sy(h),x2:735,y2:sy(h),stroke:h===0?'#506365':'#243138','stroke-width':1}),svg('text',{x:41,y:sy(h)+4,fill:'#899798','text-anchor':'end','font-size':10,'font-family':'monospace'},h.toFixed(1)));}
for(const x of[-20,-10,0,10,20])grid.append(svg('text',{x:sx(x),y:292,fill:'#899798','text-anchor':'middle','font-size':11,'font-family':'monospace'},x));grid.append(svg('text',{x:735,y:316,fill:'#899798','text-anchor':'end','font-size':10,'font-family':'monospace'},'x / local scene coordinates'));
function path(fn){let d='';for(let i=0;i<=360;i++){const x=-20+i/9;d+=(i?'L':'M')+sx(x).toFixed(2)+','+sy(fn(x)).toFixed(2)+' ';}return d;}
enabled.forEach((on,i)=>{if(on)paths.append(svg('path',{d:path(x=>TidelightMath.terms(x,y)[i]),fill:'none',stroke:waveColors[i],'stroke-width':1.2,opacity:.65}));});paths.append(svg('path',{d:path(x=>TidelightMath.height(x,y,enabled)),fill:'none',stroke:'#efe9df','stroke-width':2.7,'data-sum':'true'}));
const active=waveTerms.filter((_,i)=>enabled[i]);maths($('#wave-equation'),active.length?active.map((t,i)=>(i===0?RAW`h(x,y)=`:RAW`+\;`)+t):[RAW`h(x,y)=0`]);$('#wave-svg-description').textContent=`At y=${y}, ${enabled.filter(Boolean).length} enabled wave terms are summed. ${active.length?'Ivory is the total height.':'All terms are off, so the height is zero.'}`;}
$$('[data-wave]').forEach(x=>x.addEventListener('change',drawWave));$('#wave-y').addEventListener('input',drawWave);$('#wave-reset').addEventListener('click',()=>{$$('[data-wave]').forEach(x=>x.checked=true);$('#wave-y').value=0;drawWave();});drawWave();
let activeCase='case-A',condition='training',traceTimer=null;const paramLabels={mist_density:'Mist density',key_energy:'Sunlight energy',water_roughness:'Water roughness'};
function stopTrace(){if(traceTimer){clearInterval(traceTimer);traceTimer=null;}$('#trace-play').textContent='Replay search ▶';}
function traceRows(){return (D.traces.cases||D.traces)[activeCase];}
function drawTrace(){const rows=traceRows(),count=+$('#trace-range').value,row=rows[count-1],chart=$('#trace-svg');chart.replaceChildren();const max=Math.max(...rows.map(r=>r.objective)),min=Math.min(...rows.map(r=>r.objective)),low=Math.log10(Math.max(min,1e-9)),high=Math.log10(Math.max(max,1e-8));const sx=i=>48+i/(rows.length-1)*670,sy=v=>175-(Math.log10(Math.max(v,1e-9))-low)/(high-low||1)*140;
for(const val of[low,(low+high)/2,high]){const yy=175-(val-low)/(high-low||1)*140;chart.append(svg('line',{x1:48,y1:yy,x2:718,y2:yy,stroke:'#29353b'}),svg('text',{x:40,y:yy+4,fill:'#899798','text-anchor':'end','font-size':9,'font-family':'monospace'},Math.pow(10,val).toExponential(0)));}
let path='';rows.slice(0,count).forEach((r,i)=>path+=(i?'L':'M')+sx(i).toFixed(2)+','+sy(r.objective).toFixed(2)+' ');chart.append(svg('path',{d:path,fill:'none',stroke:'#9bcac6','stroke-width':2}),svg('circle',{cx:sx(count-1),cy:sy(row.objective),r:4,fill:'#dfa483'}),svg('text',{x:48,y:208,fill:'#899798','font-size':10,'font-family':'monospace'},'1'),svg('text',{x:718,y:208,fill:'#899798','text-anchor':'end','font-size':10,'font-family':'monospace'},'70 candidate renders · log objective axis'));
$('#trace-index').textContent=count;$('#trace-loss').textContent=row.objective.toExponential(3);$('#trace-parameters').textContent=`Candidate ${count}: mist ${row.parameters.mist_density.toFixed(5)} · sun ${row.parameters.key_energy.toFixed(4)} · roughness ${row.parameters.water_roughness.toFixed(5)}. The last attempt need not be the best fit.`;
}
function updateCase(){stopTrace();const c=D.results.cases.find(x=>x.case===activeCase);pressed('[data-case]','case',activeCase);pressed('[data-condition]','condition',condition);$('#compare-recovered').src=`assets/comparisons/${activeCase}-${condition}-recovered.webp`;$('#compare-truth').src=`assets/comparisons/${activeCase}-${condition}-truth.webp`;$('#compare-recovered').alt=`${activeCase} recovered image, ${condition}`;$('#compare-truth').alt=`${activeCase} target image, ${condition}`;$('#case-verdict').textContent=`${activeCase.toUpperCase().replace('-',' ')} / ${c.case_pass?'RECOVERED':'MISSED THE CONTROLS'}`;$('#case-verdict').classList.toggle('failed',!c.case_pass);$('#case-headline').textContent=c.case_pass?'The controls came back.':'A closer picture. The wrong controls.';$('#case-description').textContent=c.case_pass?'The fit met both parameter and image-improvement thresholds. It also held up after the camera moved and the sunlight changed.':'Mist and sunlight missed the 8% range-error limit, even though image error fell in every tested view. The fixed budget ended before the controls were accurately recovered.';const max=Math.max(...Object.values(c.normalized_parameter_errors))*100;$('#case-error').textContent=max.toFixed(max<1?3:2)+'%';$('#case-error').classList.toggle('failed',!c.case_pass);const metrics=condition==='training'?c.training:c.held_out.find(x=>x.condition===condition);$('#image-gain').textContent=(metrics.reduction*100).toFixed(2)+'%';const tbody=$('#parameter-rows');tbody.replaceChildren();for(const key of Object.keys(paramLabels)){const tr=document.createElement('tr');for(const [i,text]of[paramLabels[key],c.truth[key].toFixed(6),c.recovered[key].toFixed(6),(c.normalized_parameter_errors[key]*100).toFixed(3)+'%'].entries()){const cell=document.createElement(i===0?'th':'td');if(i===0)cell.scope='row';cell.textContent=text;if(i===3&&c.normalized_parameter_errors[key]>.08)cell.className='error';tr.append(cell);}tbody.append(tr);}$('#trace-range').max=traceRows().length;$('#trace-range').value=traceRows().length;drawTrace();}
$$('[data-case]').forEach(b=>b.addEventListener('click',()=>{activeCase=b.dataset.case;updateCase();}));$$('[data-condition]').forEach(b=>b.addEventListener('click',()=>{condition=b.dataset.condition;updateCase();}));$('#compare-split').addEventListener('input',()=>$('#compare-frame').style.setProperty('--split',$('#compare-split').value+'%'));$('#trace-range').addEventListener('input',()=>{stopTrace();drawTrace();});$('#trace-play').addEventListener('click',()=>{if(traceTimer){stopTrace();return;}$('#trace-range').value=1;drawTrace();$('#trace-play').textContent='Pause replay Ⅱ';traceTimer=setInterval(()=>{const r=$('#trace-range');if(+r.value>=+r.max){stopTrace();return;}r.value=+r.value+1;drawTrace();},150);});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTrace();});updateCase();
})();
